import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Credit","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/credit.md","filePath":"03-developer/models/credit.md"}`),a={name:`03-developer/models/credit.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="credit" tabindex="-1">Credit <a class="header-anchor" href="#credit" aria-label="Permalink to “Credit”">​</a></h1><p><strong>Model purpose:</strong> This model is used to manage a customer&#39;s financial credit in the system and can be thought of as a wallet. A customer&#39;s credit may increase when their account is topped up, increase through a refund for a returned product, or be used to pay expenses. Once all available credit has been settled, the balance can reach zero.</p><p><code>credits</code> records track financial operations related to credit. Each record stores the operation type, amount, processing status, and information related to the customer and payment.</p><h2 id="table-credits" tabindex="-1">Table: <code>credits</code> <a class="header-anchor" href="#table-credits" aria-label="Permalink to “Table: credits”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique credit transaction identifier</td></tr><tr><td><code>amount</code></td><td>DECIMAL(20,2)</td><td>No</td><td>Credit amount for the transaction</td></tr><tr><td><code>type</code></td><td>VARCHAR(255)</td><td>No</td><td>Credit operation type</td></tr><tr><td><code>status</code></td><td>VARCHAR(255)</td><td>No</td><td>Transaction processing status</td></tr><tr><td><code>customer_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Identifier of the customer associated with the transaction</td></tr><tr><td><code>invoice_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>Identifier of the associated invoice</td></tr><tr><td><code>reference_id</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Reference identifier associated with the payment method</td></tr><tr><td><code>description</code></td><td>TEXT</td><td>Yes</td><td>Transaction description</td></tr><tr><td><code>processed_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time the operation was processed</td></tr><tr><td><code>data</code></td><td>LONGTEXT</td><td>Yes</td><td>Additional transaction information in JSON format</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record soft-deletion time</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last update</td></tr><tr><td><code>payment_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>Identifier of the associated payment</td></tr></tbody></table><h2 id="additional-field-details" tabindex="-1">Additional Field Details <a class="header-anchor" href="#additional-field-details" aria-label="Permalink to “Additional Field Details”">​</a></h2><ul><li><code>amount</code>: Specifies the credit amount for the operation.</li><li><code>type</code>: Specifies the type of credit operation: <ul><li><code>CHARGE</code>: Adds credit to the customer&#39;s account.</li><li><code>PAYMENT</code>: Uses credit to make a payment.</li><li><code>REFUND</code>: Returns credit to the customer, for example, when a product is returned.</li><li><code>ADMIN_ADJUSTMENT</code>: An adjustment to the credit made by a system administrator.</li></ul></li><li><code>status</code>: Specifies the transaction processing status: <ul><li><code>PENDING</code>: The operation is awaiting processing.</li><li><code>COMPLETED</code>: The operation was completed successfully.</li><li><code>FAILED</code>: The operation failed.</li><li><code>CANCELLED</code>: The operation was cancelled.</li></ul></li><li><code>customer_id</code>: Specifies the customer to whom the credit transaction belongs. The database relationship also deletes associated credit records when the customer is deleted.</li><li><code>invoice_id</code>: Stores the identifier of the invoice if the transaction is associated with one. The database relationship also deletes the associated credit record when the invoice is deleted.</li><li><code>reference_id</code>: Stores the reference identifier associated with the payment method and is used to look up details related to <code>CreditPayment</code>.</li><li><code>description</code>: Stores a description of the operation, usually entered by an administrator or the system.</li><li><code>processed_at</code>: Specifies when the financial operation was processed.</li><li><code>data</code>: Stores additional transaction information in JSON format; for example, a message recorded when a payment succeeds or information needed to review the operation history.</li><li><code>payment_id</code>: Stores the identifier of a payment record if the credit transaction is associated with one. The database relationship restricts deletion of the associated credit record when the payment is deleted.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="fillable" tabindex="-1"><code>$fillable</code> <a class="header-anchor" href="#fillable" aria-label="Permalink to “$fillable”">​</a></h3><p>Allows the <code>customer_id</code>, <code>type</code>, <code>amount</code>, <code>status</code>, <code>payment_id</code>, <code>invoice_id</code>, <code>reference_id</code>, <code>description</code>, <code>data</code>, and <code>processed_at</code> fields to be mass-assigned on the model.</p><h3 id="casts" tabindex="-1"><code>$casts</code> <a class="header-anchor" href="#casts" aria-label="Permalink to “$casts”">​</a></h3><p>Specifies the data types used by the model when reading and writing fields:</p><ul><li><code>data</code>: Cast to an array.</li><li><code>processed_at</code>: Cast to a date-time (<code>datetime</code>) object.</li><li><code>amount</code>: Cast to an integer (<code>int</code>).</li></ul><p><strong>Note:</strong> The <code>amount</code> column type in the database is <code>DECIMAL(20,2)</code>, but the current cast converts it to <code>int</code>. If fractional amounts need to be preserved, this cast should be reviewed.</p><h3 id="types" tabindex="-1"><code>$types</code> <a class="header-anchor" href="#types" aria-label="Permalink to “$types”">​</a></h3><p>Provides an array of the allowed credit operation types: <code>CHARGE</code>, <code>PAYMENT</code>, <code>REFUND</code>, and <code>ADMIN_ADJUSTMENT</code>.</p><h3 id="statuses" tabindex="-1"><code>$statuses</code> <a class="header-anchor" href="#statuses" aria-label="Permalink to “$statuses”">​</a></h3><p>Provides the defined statuses for credit transactions: <code>PENDING</code>, <code>COMPLETED</code>, <code>FAILED</code>, and <code>CANCELLED</code>.</p><h3 id="customer" tabindex="-1"><code>customer()</code> <a class="header-anchor" href="#customer" aria-label="Permalink to “customer()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./customer.html">Customer</a> model and returns the customer associated with the transaction.</p><h3 id="payment" tabindex="-1"><code>payment()</code> <a class="header-anchor" href="#payment" aria-label="Permalink to “payment()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./payment.html">Payment</a> model and returns the payment associated with the transaction through <code>payment_id</code>.</p><h3 id="invoice" tabindex="-1"><code>invoice()</code> <a class="header-anchor" href="#invoice" aria-label="Permalink to “invoice()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./invoice.html">Invoice</a> model and returns the invoice associated with the transaction through <code>invoice_id</code>.</p><h3 id="ischarge" tabindex="-1"><code>isCharge()</code> <a class="header-anchor" href="#ischarge" aria-label="Permalink to “isCharge()”">​</a></h3><p>Checks whether the transaction type is <code>CHARGE</code>; returns <code>true</code> if so, and <code>false</code> otherwise.</p><h3 id="ispayment" tabindex="-1"><code>isPayment()</code> <a class="header-anchor" href="#ispayment" aria-label="Permalink to “isPayment()”">​</a></h3><p>Checks whether the transaction type is <code>PAYMENT</code>; returns <code>true</code> if so, and <code>false</code> otherwise.</p><h3 id="iscompleted" tabindex="-1"><code>isCompleted()</code> <a class="header-anchor" href="#iscompleted" aria-label="Permalink to “isCompleted()”">​</a></h3><p>Checks whether the transaction status is <code>COMPLETED</code>; returns <code>true</code> if so, and <code>false</code> otherwise.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};